"""Criteria for `overlapping-groups-need-shared-mutex`.

Both halves must be tested, and the second is more important:

1. **Report the right cases**—overlapping addresses with different mutex IDs must be reported, with a per-slot
comparison.
2. **Parse realistic source forms**—examples use many forms for `type=` (helpers, default arguments, local bindings,
dict/list indexing, and comprehensions). **A rule that cannot parse a case reports zero findings, which is equivalent to
having no rule**, so pin each form with a test. The `init_output` rule failed because it “could not catch the case that
motivated it.”
"""

import ast
from pathlib import Path

from _checks import mutex_overlap
from _checks.source import has_decorator

RULE = mutex_overlap.RULE

PREAMBLE = "import pypto_pro.language as pl\n\nFP32 = pl.DT_FP32\n"

VEC = "target_memory=pl.MemorySpace.Vec"
T8x8 = f"pl.TileType(shape=[8, 8], dtype=FP32, {VEC})"  # 8*8*4 = 256 bytes = 0x100


JIT = "@pl.jit()"
"""Default decorator. **`auto_mutex` defaults to True** (`runtime/jit.py`), so bare `@pl.jit()` is also covered."""


def _write(
    tmp_path: Path, body: str, *, module: str = "", decorator: str = JIT
) -> Path:
    text = PREAMBLE + module + f"\n\n{decorator}\ndef _kernel(x, out):\n" + body
    path = tmp_path / "kernel.py"
    path.write_text(text, encoding="utf-8")
    return path


BODY = 8
"""Line number of the first function-body line in a file generated by `_write` when `module=""`: three preamble lines +
two blank lines + decorator + def. **Counted from generated text, not guessed.**"""


def _hits(path: Path) -> list[tuple[int, str, bool]]:
    return [(f.lineno, f.rule, f.waived) for f in mutex_overlap.check(path)]


def _groups_of(path: Path) -> list[mutex_overlap.Group]:
    """Return a group parsed from the first `@pl.jit` in this file. Used for the “parse realistic source forms” half."""
    source = mutex_overlap.read(path)
    env = mutex_overlap._constants(source)
    for node in ast.walk(source.tree):
        if has_decorator(node, source.pl, "jit"):
            return mutex_overlap._groups(source, node, env)
    return []


# ---------------------------------------------------------------------------
# Reported cases
# ---------------------------------------------------------------------------


def test_overlapping_groups_with_disjoint_ids_are_reported(tmp_path):
    """The core case for this rule: both groups start at `0x0` and span 0x100 bytes, but use mutex IDs 0 and 1."""
    path = _write(
        tmp_path,
        f"    a = pl.make_tile_group(type={T8x8}, addrs=[0x0], mutex_ids=[0])\n"
        f"    b = pl.make_tile_group(type={T8x8}, addrs=[0x0], mutex_ids=[1])\n",
    )
    assert _hits(path) == [
        (9, RULE, False)
    ]  # Report on the second group's declaration line.


def test_partial_overlap_of_the_byte_range_counts(tmp_path):
    """Any intersecting ranges count; their starting addresses need not match: `[0x0, 0x100)` and `[0x80, 0x180)`."""
    path = _write(
        tmp_path,
        f"    a = pl.make_tile_group(type={T8x8}, addrs=[0x0], mutex_ids=[0])\n"
        f"    b = pl.make_tile_group(type={T8x8}, addrs=[0x80], mutex_ids=[1])\n",
    )
    assert len(_hits(path)) == 1


def test_the_check_is_per_slot_not_per_group(tmp_path):
    """**Whole-group comparison would miss this case.** A has IDs `[0, 1]`, B has `[1, 2]`, so the ID sets intersect,
    but the overlapping slots are A's slot 0 (ID 0) and B's slot 1 (ID 2), whose IDs differ.

    Addresses: A = `0x0` / `0x100`; B = `0x200` / `0x0`.
    """
    path = _write(
        tmp_path,
        f"    a = pl.make_tile_group(type={T8x8}, addrs=[0x0, 0x100], mutex_ids=[0, 1])\n"
        f"    b = pl.make_tile_group(type={T8x8}, addrs=[0x200, 0x0], mutex_ids=[1, 2])\n",
    )
    assert len(_hits(path)) == 1


def test_the_message_names_both_slots_and_both_ids(tmp_path):
    """The message must be diagnostic: identify both slots, the memory space, and both IDs."""
    path = _write(
        tmp_path,
        f"    a = pl.make_tile_group(type={T8x8}, addrs=[0x0], mutex_ids=[0])\n"
        f"    b = pl.make_tile_group(type={T8x8}, addrs=[0x0], mutex_ids=[7])\n",
    )
    rendered = str(mutex_overlap.check(path)[0])
    assert "0x0" in rendered and "0x100" in rendered
    assert "pl.MemorySpace.Vec" in rendered
    assert "7" in rendered and "0" in rendered
    assert "8 行" in rendered  # Points back to the other group's declaration line.


def test_a_scalar_addrs_lays_slots_out_contiguously(tmp_path):
    """`addrs=<scalar>` means `base + i * slot_size` (mirroring `_buffer_parser`). The second group overlaps the
    **second slot** of the first group.
    """
    path = _write(
        tmp_path,
        f"    a = pl.make_tile_group(type={T8x8}, addrs=0x0, mutex_ids=[0, 1])\n"
        f"    b = pl.make_tile_group(type={T8x8}, addrs=[0x100], mutex_ids=[5])\n",
    )
    assert len(_hits(path)) == 1


def test_three_groups_report_each_conflicting_pair(tmp_path):
    path = _write(
        tmp_path,
        f"    a = pl.make_tile_group(type={T8x8}, addrs=[0x0], mutex_ids=[0])\n"
        f"    b = pl.make_tile_group(type={T8x8}, addrs=[0x0], mutex_ids=[1])\n"
        f"    c = pl.make_tile_group(type={T8x8}, addrs=[0x0], mutex_ids=[2])\n",
    )
    assert len(_hits(path)) == 3


# ---------------------------------------------------------------------------
# Non-reported cases
# ---------------------------------------------------------------------------


def test_overlapping_groups_sharing_the_id_are_fine(tmp_path):
    """Same address with the same lock is valid—a single lock really does cover that memory."""
    path = _write(
        tmp_path,
        f"    a = pl.make_tile_group(type={T8x8}, addrs=[0x0], mutex_ids=[3])\n"
        f"    b = pl.make_tile_group(type={T8x8}, addrs=[0x0], mutex_ids=[3])\n",
    )
    assert _hits(path) == []


def test_different_memory_spaces_never_overlap(tmp_path):
    """**Without this check, the entire example library would be flooded with false positives.** Vec and Mat are
    separate address spaces; the same numeric address refers to different memory in each.
    """
    mat = "pl.TileType(shape=[8, 8], dtype=FP32, target_memory=pl.MemorySpace.Mat)"
    path = _write(
        tmp_path,
        f"    a = pl.make_tile_group(type={T8x8}, addrs=[0x0], mutex_ids=[0])\n"
        f"    b = pl.make_tile_group(type={mat}, addrs=[0x0], mutex_ids=[1])\n",
    )
    assert _hits(path) == []


def test_groups_that_do_not_overlap_are_fine(tmp_path):
    path = _write(
        tmp_path,
        f"    a = pl.make_tile_group(type={T8x8}, addrs=[0x0], mutex_ids=[0])\n"
        f"    b = pl.make_tile_group(type={T8x8}, addrs=[0x100], mutex_ids=[1])\n",
    )
    assert _hits(path) == []


def test_two_groups_in_different_kernels_are_not_compared(tmp_path):
    """Scope is one `@pl.jit`; two separate kernels may reuse addresses."""
    text = (
        PREAMBLE + f"\n\n{JIT}\ndef k1(x, out):\n"
        f"    a = pl.make_tile_group(type={T8x8}, addrs=[0x0], mutex_ids=[0])\n"
        f"\n\n{JIT}\ndef k2(x, out):\n"
        f"    b = pl.make_tile_group(type={T8x8}, addrs=[0x0], mutex_ids=[1])\n"
    )
    path = tmp_path / "kernel.py"
    path.write_text(text, encoding="utf-8")
    assert _hits(path) == []


def test_a_group_without_mutex_ids_is_skipped(tmp_path):
    """A group without `mutex_ids` means the author manages synchronization; it belongs to
    `auto-mutex-needs-tile-group`, not this rule.
    """
    path = _write(
        tmp_path,
        f"    a = pl.make_tile_group(type={T8x8}, addrs=[0x0], depth=2)\n"
        f"    b = pl.make_tile_group(type={T8x8}, addrs=[0x0], mutex_ids=[1])\n",
    )
    assert _hits(path) == []


def test_an_unresolvable_address_is_skipped(tmp_path):
    """**A gate must have zero false positives**, so skip values that cannot be reduced to constants, just like the
    framework.
    """
    path = _write(
        tmp_path,
        f"    a = pl.make_tile_group(type={T8x8}, addrs=[x], mutex_ids=[0])\n"
        f"    b = pl.make_tile_group(type={T8x8}, addrs=[0x0], mutex_ids=[1])\n",
    )
    assert _hits(path) == []


def test_a_non_literal_memory_space_is_skipped(tmp_path):
    """Guessing the memory space could report unrelated regions as overlapping—do not guess."""
    path = _write(
        tmp_path,
        "    t = pl.TileType(shape=[8, 8], dtype=FP32, target_memory=space)\n"
        f"    a = pl.make_tile_group(type=t, addrs=[0x0], mutex_ids=[0])\n"
        f"    b = pl.make_tile_group(type={T8x8}, addrs=[0x0], mutex_ids=[1])\n",
    )
    assert _hits(path) == []


def test_only_an_explicit_auto_mutex_false_turns_it_off(tmp_path):
    """**Scope boundary, and I previously had it backwards.** `auto_mutex` defaults to `True` (`auto_mutex: bool = True`
    in `runtime/jit.py`), so bare `@pl.jit()` also inserts locks. Only explicit `auto_mutex=False` disables them.
    """
    body = (
        f"    a = pl.make_tile_group(type={T8x8}, addrs=[0x0], mutex_ids=[0])\n"
        f"    b = pl.make_tile_group(type={T8x8}, addrs=[0x0], mutex_ids=[1])\n"
    )
    assert len(_hits(_write(tmp_path, body, decorator="@pl.jit()"))) == 1
    assert len(_hits(_write(tmp_path, body, decorator="@pl.jit(auto_mutex=True)"))) == 1
    assert _hits(_write(tmp_path, body, decorator="@pl.jit(auto_mutex=False)")) == []


def test_auto_mutex_as_a_variable_is_not_taken_as_off(tmp_path):
    """`auto_mutex=FLAG` cannot be resolved statically. **Do not treat uncertainty as disabled**; missing a real defect
    is worse.
    """
    path = _write(
        tmp_path,
        f"    a = pl.make_tile_group(type={T8x8}, addrs=[0x0], mutex_ids=[0])\n"
        f"    b = pl.make_tile_group(type={T8x8}, addrs=[0x0], mutex_ids=[1])\n",
        decorator="@pl.jit(auto_mutex=FLAG)",
    )
    assert len(_hits(path)) == 1


def test_a_file_without_the_pl_import_is_skipped(tmp_path):
    path = tmp_path / "kernel.py"
    path.write_text("x = 1\n", encoding="utf-8")
    assert mutex_overlap.check(path) == []


# ---------------------------------------------------------------------------
# Parseable forms: actual `type=` / `addrs=` patterns in examples
# ---------------------------------------------------------------------------


def test_a_local_tile_type_binding_resolves(tmp_path):
    """`tt = pl.TileType(...)` followed by `type=tt`—six groups sharing one type in a kernel is common."""
    path = _write(
        tmp_path,
        f"    tt = {T8x8}\n"
        "    a = pl.make_tile_group(type=tt, addrs=[0x0], mutex_ids=[0])\n"
        "    b = pl.make_tile_group(type=tt, addrs=[0x0], mutex_ids=[1])\n",
    )
    assert len(_hits(path)) == 1


def test_a_module_level_helper_resolves(tmp_path):
    """`def _tile_type(dtype): return pl.TileType(..., dtype=dtype, ...)`.
    **Most of the 351 measured `make_tile_group` calls in examples use this form**; without support, the rule would be
    decorative.
    """
    path = _write(
        tmp_path,
        "    a = pl.make_tile_group(type=_tt(FP32), addrs=[0x0], mutex_ids=[0])\n"
        "    b = pl.make_tile_group(type=_tt(FP32), addrs=[0x0], mutex_ids=[1])\n",
        module=f"\n\ndef _tt(dtype):\n    return pl.TileType(shape=[8, 8], dtype=dtype, {VEC})\n",
    )
    assert len(_hits(path)) == 1


def test_helper_default_arguments_resolve(tmp_path):
    """`def _ub(dtype=FP32, n=N)` used with `_ub()`—as in the `block_grid` / `dtype_carriers` batch."""
    path = _write(
        tmp_path,
        "    a = pl.make_tile_group(type=_ub(), addrs=[0x0], mutex_ids=[0])\n"
        "    b = pl.make_tile_group(type=_ub(), addrs=[0x0], mutex_ids=[1])\n",
        module=f"\nN = 8\n\n\ndef _ub(dtype=FP32, n=N):\n"
        f"    return pl.TileType(shape=[1, n], dtype=dtype, {VEC})\n",
    )
    assert len(_hits(path)) == 1


def test_a_local_binding_of_a_helper_call_resolves(tmp_path):
    """`tt = _tt(FP32)` binds a **helper call** locally, so resolve one more layer. Without that layer, 48 measured
    cases stopped here.
    """
    path = _write(
        tmp_path,
        "    tt = _tt(FP32)\n"
        "    a = pl.make_tile_group(type=tt, addrs=[0x0], mutex_ids=[0])\n"
        "    b = pl.make_tile_group(type=tt, addrs=[0x0], mutex_ids=[1])\n",
        module=f"\n\ndef _tt(dtype):\n    return pl.TileType(shape=[8, 8], dtype=dtype, {VEC})\n",
    )
    assert len(_hits(path)) == 1


def test_a_rebound_local_name_is_skipped(tmp_path):
    """Skip the whole group when a name is rebound; it is better to miss a case than follow the wrong value."""
    path = _write(
        tmp_path,
        f"    tt = {T8x8}\n"
        f"    tt = pl.TileType(shape=[1, 1], dtype=FP32, {VEC})\n"
        "    a = pl.make_tile_group(type=tt, addrs=[0x0], mutex_ids=[0])\n"
        "    b = pl.make_tile_group(type=tt, addrs=[0x0], mutex_ids=[1])\n",
    )
    assert _hits(path) == []


def test_tuple_unpacking_at_module_level_resolves(tmp_path):
    """`TM, TN = 16, 64`—all six groups in `entry_and_loop` depend on this assignment."""
    path = _write(
        tmp_path,
        f"    a = pl.make_tile_group(type=pl.TileType(shape=[TM, TN], dtype=FP32, {VEC}),"
        " addrs=[0x0], mutex_ids=[0])\n"
        f"    b = pl.make_tile_group(type=pl.TileType(shape=[TM, TN], dtype=FP32, {VEC}),"
        " addrs=[0x0], mutex_ids=[1])\n",
        module="\nTM, TN = 8, 8\n",
    )
    assert len(_hits(path)) == 1


def test_a_dict_address_table_resolves(tmp_path):
    """`_ADDR = {"a": 0x0}` paired with `addrs=[_ADDR["a"]]`—used eight times in one `vf_arith` kernel."""
    path = _write(
        tmp_path,
        f'    a = pl.make_tile_group(type={T8x8}, addrs=[_ADDR["a"]], mutex_ids=[0])\n'
        f'    b = pl.make_tile_group(type={T8x8}, addrs=[_ADDR["b"]], mutex_ids=[1])\n',
        module='\n_ADDR = {"a": 0x0, "b": 0x80}\n',
    )
    assert len(_hits(path)) == 1


def test_a_list_comprehension_address_table_resolves(tmp_path):
    """`_O = [_A + STEP * (i + 1) for i in range(5)]`—the address table in `vf_align`."""
    path = _write(
        tmp_path,
        f"    a = pl.make_tile_group(type={T8x8}, addrs=[_O[0]], mutex_ids=[0])\n"
        f"    b = pl.make_tile_group(type={T8x8}, addrs=[_O[0]], mutex_ids=[1])\n",
        module="\n_A = 0\nSTEP = 0x100\n_O = [_A + STEP * (i + 1) for i in range(5)]\n",
    )
    groups = _groups_of(path)
    assert [g.slots[0][0] for g in groups] == [0x100, 0x100]
    assert len(_hits(path)) == 1


def test_a_comprehension_with_a_condition_is_not_folded(tmp_path):
    """Do not fold comprehensions with an `if`—**deliberately avoid `eval`**; a gate must not execute expressions from
    the checked file.
    """
    path = _write(
        tmp_path,
        f"    a = pl.make_tile_group(type={T8x8}, addrs=[_O[0]], mutex_ids=[0])\n"
        f"    b = pl.make_tile_group(type={T8x8}, addrs=[_O[0]], mutex_ids=[1])\n",
        module="\n_O = [i for i in range(5) if i > 1]\n",
    )
    assert _hits(path) == []


def test_the_slot_size_mirrors_the_framework_formula(tmp_path):
    """`prod(shape) * ceil(bits / 8)`, mirroring `_cross_core_scanner._tile_type_slot_size`.
    **`BOOL` is 8 bits, not 1; 4-bit dtypes round up to 1 byte per element**—the framework uses the same slot
    spacing.
    """
    for dtype, per_elem in (
        ("FP32", 4),
        ("FP16", 2),
        ("INT8", 1),
        ("BOOL", 1),
        ("FP4E2M1", 1),
    ):
        path = _write(
            tmp_path,
            f"    a = pl.make_tile_group(type=pl.TileType(shape=[1, 8],"
            f" dtype=pl.DT_{dtype}, {VEC}), addrs=0x0, mutex_ids=[0, 1])\n",
        )
        slots = _groups_of(path)[0].slots
        assert slots[0] == (0, 8 * per_elem), dtype
        assert slots[1][0] == 8 * per_elem, dtype


def test_an_unknown_dtype_is_skipped(tmp_path):
    """Do not guess dtypes absent from the bit-width table; a wrong guess changes slot spacing and creates false
    positives.
    """
    path = _write(
        tmp_path,
        f"    a = pl.make_tile_group(type=pl.TileType(shape=[1, 8], dtype=pl.DT_MADEUP,"
        f" {VEC}), addrs=[0x0], mutex_ids=[0])\n"
        f"    b = pl.make_tile_group(type={T8x8}, addrs=[0x0], mutex_ids=[1])\n",
    )
    assert _hits(path) == []


# ---------------------------------------------------------------------------
# `反例：` declarations
# ---------------------------------------------------------------------------


def test_a_declared_counterexample_is_waived_not_hidden(tmp_path):
    """Still print waived findings; only exclude them from the failure count. A hidden waiver is equivalent to no
    waiver.
    """
    body = (
        f'    """演示。\n\n    反例：{RULE} —— 这一例的内容就是这条违规本身\n    """\n'
        f"    a = pl.make_tile_group(type={T8x8}, addrs=[0x0], mutex_ids=[0])\n"
        f"    b = pl.make_tile_group(type={T8x8}, addrs=[0x0], mutex_ids=[1])\n"
    )
    path = _write(tmp_path, body)
    hits = _hits(path)
    assert len(hits) == 1 and hits[0][2] is True


def test_a_stale_counterexample_declaration_is_itself_an_error(tmp_path):
    """Waivers can go stale. If a counterexample becomes compliant but its declaration remains, it can hide a real
    future violation.
    """
    body = (
        f'    """演示。\n\n    反例：{RULE} —— 已经不成立了\n    """\n'
        f"    a = pl.make_tile_group(type={T8x8}, addrs=[0x0], mutex_ids=[0])\n"
        f"    b = pl.make_tile_group(type={T8x8}, addrs=[0x100], mutex_ids=[1])\n"
    )
    path = _write(tmp_path, body)
    hits = _hits(path)
    assert len(hits) == 1 and hits[0][2] is False
